import java.util.*;

class mcf_graph_int_cost {
    private int n;
    private List<int[]> pos;
    private List<List<_edge>> g;
    private long[] dual;
    private long[] dist;
    private int[] pv;
    private int[] pe;
    private boolean[] vis;

    private static final long INF = 4294967295L;

    public mcf_graph_int_cost(int n) {
        this.n = n;
        pos = new ArrayList<>();
        g = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }
    }

    public int add_edge(int from, int to, long cap, long cost) {
        int m = pos.size();
        pos.add(new int[]{from, g.get(from).size()});
        g.get(from).add(new _edge(to, g.get(to).size(), cap, cost));
        g.get(to).add(new _edge(from, g.get(from).size() - 1, 0, -cost));
        return m;
    }

    public static class Edge {
        public int from;
        public int to;
        public long cap;
        public long flow;
        public long cost;

        public Edge(int from, int to, long cap, long flow, long cost) {
            this.from = from;
            this.to = to;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    public Edge get_edge(int i) {
        _edge e = g.get(pos.get(i)[0]).get(pos.get(i)[1]);
        _edge re = g.get(e.to).get(e.rev);
        return new Edge(pos.get(i)[0], e.to, e.cap + re.cap, re.cap, e.cost);
    }

    public List<Edge> edges() {
        List<Edge> ret = new ArrayList<>();
        for (int i = 0; i < pos.size(); i++) {
            _edge e = g.get(pos.get(i)[0]).get(pos.get(i)[1]);
            _edge re = g.get(e.to).get(e.rev);
            ret.add(new Edge(pos.get(i)[0], e.to, e.cap + re.cap, re.cap, e.cost));
        }
        return ret;
    }

    private boolean _dual_ref(int s, int t) {
        Arrays.fill(dist, INF);
        Arrays.fill(pv, -1);
        Arrays.fill(pe, -1);
        Arrays.fill(vis, false);

        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        dist[s] = 0;
        pq.offer(new long[]{0, s});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int v = (int) cur[1];
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;

            for (int i = 0; i < g.get(v).size(); i++) {
                _edge e = g.get(v).get(i);
                if (vis[e.to] || e.cap == 0) continue;
                long cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.offer(new long[]{dist[e.to] << 32 | e.to, e.to});
                }
            }
        }

        if (!vis[t]) return false;

        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }

    public List<long[]> slope(int s, int t, long flow_limit) {
        dual = new long[n];
        dist = new long[n];
        pv = new int[n];
        pe = new int[n];
        vis = new boolean[n];

        long flow = 0;
        long cost = 0;
        long prev_cost = -1;
        List<long[]> result = new ArrayList<>();
        result.add(new long[]{flow, cost});

        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;

            long c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                _edge e = g.get(pv[v]).get(pe[v]);
                e.cap -= c;
                g.get(v).get(e.rev).cap += c;
                v = pv[v];
            }
            long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                result.remove(result.size() - 1);
            }
            result.add(new long[]{flow, cost});
            prev_cost = cost;
        }
        return result;
    }

    public long[] flow(int s, int t, long flow_limit) {
        List<long[]> slopes = slope(s, t, flow_limit);
        return slopes.get(slopes.size() - 1);
    }

    static class _edge {
        int to;
        int rev;
        long cap;
        long cost;

        _edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a1 = sc.nextInt();
        int a2 = sc.nextInt();
        int a3 = sc.nextInt();
        int b1 = sc.nextInt();
        int b2 = sc.nextInt();
        int b3 = sc.nextInt();

        long INF = (long) 1e9;

        mcf_graph_int_cost g = new mcf_graph_int_cost(8);
        g.add_edge(0, 1, a1, 0);
        g.add_edge(0, 2, a2, 0);
        g.add_edge(0, 3, a3, 0);
        g.add_edge(4, 7, b1, 0);
        g.add_edge(5, 7, b2, 0);
        g.add_edge(6, 7, b3, 0);
        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                long cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.add_edge(i, j, INF, cost);
            }
        }

        long[] result = g.flow(0, 7, mcf_graph_int_cost.INF);
        long ans1 = result[0];

        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}

