import java.util.*;

public class Main {
    static final long INF = 1000000000L; // 10^9

    static class MCF {
        int n;
        List<int[]> pos; // store (vertex, index) pairs for each added edge
        List<List<_Edge>> g;

        MCF(int n) {
            this.n = n;
            pos = new ArrayList<>();
            g = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
        }

        int addEdge(int fr, int to, long cap, long cost) {
            int m = pos.size();
            pos.add(new int[]{fr, g.get(fr).size()});
            g.get(fr).add(new _Edge(to, g.get(to).size(), cap, cost));
            g.get(to).add(new _Edge(fr, g.get(fr).size() - 1, 0, -cost));
            return m;
        }

        static class Edge {
            int fr, to;
            long cap, flow, cost;
            Edge(int fr, int to, long cap, long flow, long cost) {
                this.fr = fr;
                this.to = to;
                this.cap = cap;
                this.flow = flow;
                this.cost = cost;
            }
        }

        Edge getEdge(int i) {
            int[] p = pos.get(i);
            _Edge e = g.get(p[0]).get(p[1]);
            _Edge re = g.get(e.to).get(e.rev);
            return new Edge(p[0], e.to, e.cap + re.cap, re.cap, e.cost);
        }

        List<Edge> edges() {
            List<Edge> res = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                int[] p = pos.get(i);
                _Edge e = g.get(p[0]).get(p[1]);
                _Edge re = g.get(e.to).get(e.rev);
                res.add(new Edge(p[0], e.to, e.cap + re.cap, re.cap, e.cost));
            }
            return res;
        }

        // Bellman-Ford to find shortest path from s to t
        boolean bellmanFord(int s, int t) {
            long INF_DIST = Long.MAX_VALUE / 2;
            long[] dist = new long[n];
            int[] pv = new int[n];
            int[] pe = new int[n];
            Arrays.fill(dist, INF_DIST);
            Arrays.fill(pv, -1);
            Arrays.fill(pe, -1);
            dist[s] = 0;
            for (int iter = 0; iter < n - 1; iter++) {
                boolean updated = false;
                for (int v = 0; v < n; v++) {
                    if (dist[v] == INF_DIST) continue;
                    List<_Edge> edges = g.get(v);
                    for (int i = 0; i < edges.size(); i++) {
                        _Edge e = edges.get(i);
                        if (e.cap == 0) continue;
                        long nd = dist[v] + e.cost;
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            updated = true;
                        }
                    }
                }
                if (!updated) break;
            }
            if (dist[t] == INF_DIST) return false;
            // store for later use
            this.pv = pv;
            this.pe = pe;
            this.dist = dist;
            return true;
        }

        int[] pv;
        int[] pe;
        long[] dist;

        List<long[]> slope(int s, int t, long flowLimit) {
            long flow = 0;
            long cost = 0;
            long prevCost = -1;
            List<long[]> result = new ArrayList<>();
            result.add(new long[]{flow, cost});
            while (flow < flowLimit) {
                if (!bellmanFord(s, t)) break;
                long c = flowLimit - flow;
                int v = t;
                while (v != s) {
                    c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                    v = pv[v];
                }
                v = t;
                while (v != s) {
                    _Edge e = g.get(pv[v]).get(pe[v]);
                    e.cap -= c;
                    g.get(v).get(e.rev).cap += c;
                    v = pv[v];
                }
                long d = dist[t];
                flow += c;
                cost += c * d;
                if (prevCost == d) {
                    result.remove(result.size() - 1);
                }
                result.add(new long[]{flow, cost});
                prevCost = d;
            }
            return result;
        }

        long[] flow(int s, int t, long flowLimit) {
            List<long[]> sl = slope(s, t, flowLimit);
            return sl.get(sl.size() - 1);
        }

        long[] flow(int s, int t) {
            return flow(s, t, Long.MAX_VALUE);
        }

        static class _Edge {
            int to, rev;
            long cap, cost;
            _Edge(int to, int rev, long cap, long cost) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cost = cost;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); // not used
        long a1 = sc.nextLong();
        long a2 = sc.nextLong();
        long a3 = sc.nextLong();
        long b1 = sc.nextLong();
        long b2 = sc.nextLong();
        long b3 = sc.nextLong();

        MCF g = new MCF(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);
        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                long cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, INF, cost);
            }
        }

        long[] res = g.flow(0, 7);
        long ans1 = res[1]; // cost
        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}

