import java.util.*;
import java.lang.*;
import java.io.*;
import java.math.*;

public class Main {
    static final int MOD = 998244353;
    static final long mod = 998244353;

    public static long inv_mod(long n) {
        return BigInteger.valueOf(n).modPow(BigInteger.valueOf(mod - 2), BigInteger.valueOf(mod)).longValue();
    }

    public static List<Long> factors(long n) {
        Set<Long> set = new TreeSet<>();
        for (long i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                set.add(i);
                set.add(n / i);
            }
        }
        return new ArrayList<>(set);
    }

    public static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] readIntArray() {
            String[] tokens = nextLine().split(" ");
            int[] arr = new int[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                arr[i] = Integer.parseInt(tokens[i]);
            }
            return arr;
        }
    }

    public static int match(int a, int b) {
        if (a == b) return 0;
        else if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
        else return -1;
    }

    public static int give(ArrayList<ArrayList<Integer>> l1, ArrayList<ArrayList<Integer>> l2) {
        int ans = 0;
        int[] curr1 = null;
        int[] curr2 = null;
        while (!l1.isEmpty() || !l2.isEmpty()) {
            try {
                if (curr1 == null) {
                    ArrayList<Integer> temp = l1.remove(l1.size()-1);
                    curr1 = new int[]{temp.get(0), temp.get(1)};
                }
                if (curr2 == null) {
                    ArrayList<Integer> temp = l2.remove(l2.size()-1);
                    curr2 = new int[]{temp.get(0), temp.get(1)};
                }
            } catch (Exception e) {
                return ans;
            }

            int m = match(curr1[1], curr2[1]);
            ans += Math.max(0, Math.min(curr1[0], curr2[0]) * m);
            if (curr1[0] < curr2[0]) {
                curr2[0] -= curr1[0];
                curr1 = null;
            } else if (curr1[0] > curr2[0]) {
                curr1[0] -= curr2[0];
                curr2 = null;
            } else {
                curr1 = null;
                curr2 = null;
            }
        }
        return ans;
    }

    public static int maximum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        return Math.min(rock1, sci2) + Math.min(sci1, paper2) + Math.min(paper1, rock2);
    }

    public static int minimum(int n, int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        int ans = n;
        int[][] base1 = {{rock1, 1}, {sci1, 2}, {paper1, 3}};
        int[][] base2 = {{rock2, 1}, {sci2, 2}, {paper2, 3}};

        List<int[][]> perms1 = permute(base1);
        List<int[][]> perms2 = permute(base2);

        ans = Integer.MAX_VALUE;
        for (int[][] p1 : perms1) {
            for (int[][] p2 : perms2) {
                ArrayList<ArrayList<Integer>> l1 = new ArrayList<>();
                ArrayList<ArrayList<Integer>> l2 = new ArrayList<>();
                for (int[] arr : p1) {
                    l1.add(new ArrayList<>(Arrays.asList(arr[0], arr[1])));
                }
                for (int[] arr : p2) {
                    l2.add(new ArrayList<>(Arrays.asList(arr[0], arr[1])));
                }
                ans = Math.min(ans, give(l1, l2));
            }
        }
        return ans;
    }

    public static List<int[][]> permute(int[][] arr) {
        List<int[][]> result = new ArrayList<>();
        permuteHelper(arr, 0, result);
        return result;
    }

    private static void permuteHelper(int[][] arr, int index, List<int[][]> result) {
        if (index == arr.length) {
            int[][] copy = new int[arr.length][2];
            for (int i = 0; i < arr.length; i++) {
                copy[i] = arr[i].clone();
            }
            result.add(copy);
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            permuteHelper(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private static void swap(int[][] arr, int i, int j) {
        int[] temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int[] vals1 = fr.readIntArray();
        int rock1 = vals1[0], sci1 = vals1[1], paper1 = vals1[2];
        int[] vals2 = fr.readIntArray();
        int rock2 = vals2[0], sci2 = vals2[1], paper2 = vals2[2];

        int max = maximum(rock1, sci1, paper1, rock2, sci2, paper2);
        int min = minimum(n, rock1, sci1, paper1, rock2, sci2, paper2);
        System.out.println(min + " " + max);
    }
}

