public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int round = Integer.parseInt(scanner.nextLine());
        String[] firstPersonStr = scanner.nextLine().split(" ");
        String[] secondPersonStr = scanner.nextLine().split(" ");

        int[] firstPerson = new int[3];
        int[] secondPerson = new int[3];
        for (int i = 0; i < 3; i++) {
            firstPerson[i] = Integer.parseInt(firstPersonStr[i]);
            secondPerson[i] = Integer.parseInt(secondPersonStr[i]);
        }

        solve(round, firstPerson, secondPerson);
        scanner.close();
    }

    public static void solve(int round, int[] firstPerson, int[] secondPerson) {
        // find max win
        int win = 0;
        int[] secondPersonExtended = new int[4];
        for (int i = 0; i < 3; i++) {
            secondPersonExtended[i] = secondPerson[i];
        }
        secondPersonExtended[3] = secondPerson[0]; // append first to end

        for (int i = 0; i < 3; i++) {
            int findless;
            if (firstPerson[i] <= secondPersonExtended[i + 1]) {
                findless = firstPerson[i];
            } else {
                findless = secondPersonExtended[i + 1];
            }
            win += findless;
        }

        // find min win (actually min loss or remaining)
        int[] secondPersonShifted = new int[3];
        secondPersonShifted[0] = secondPerson[2];
        secondPersonShifted[1] = secondPerson[0];
        secondPersonShifted[2] = secondPerson[1];

        int[] firstCopy = new int[3];
        int[] secondCopy = new int[3];
        for (int i = 0; i < 3; i++) {
            firstCopy[i] = firstPerson[i];
            secondCopy[i] = secondPersonShifted[i];
        }

        for (int i = 0; i < 3; i++) {
            if (firstCopy[i] > 0) {
                int diff = Math.min(firstCopy[i], secondCopy[i]);
                firstCopy[i] -= diff;
                secondCopy[i] -= diff;
                if (firstCopy[i] > 0) {
                    diff = Math.min(firstCopy[i], secondCopy[(i + 1) % 3]);
                    firstCopy[i] -= diff;
                    secondCopy[(i + 1) % 3] -= diff;
                }
            }
        }

        int minWin = firstCopy[0] + firstCopy[1] + firstCopy[2];
        System.out.println(minWin + " " + win);
    }
}

