import java.util.*;

public class Main {
    static int[][] pairings = {
        {0, 0}, // 1: a1 with b1
        {0, 2}, // 2: a1 with b3
        {1, 1}, // 3: a2 with b2
        {1, 0}, // 4: a2 with b1
        {2, 2}, // 5: a3 with b3
        {2, 1}  // 6: a3 with b2
    };

    static int maxSum = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[3];
        int[] b = new int[3];
        for (int i = 0; i < 3; i++) a[i] = sc.nextInt();
        for (int i = 0; i < 3; i++) b[i] = sc.nextInt();

        int mx = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);

        // Generate all permutations of indices 0..5
        boolean[] used = new boolean[6];
        int[] perm = new int[6];
        maxSum = 0;
        permute(0, used, perm, a, b);

        System.out.print((n - maxSum) + " " + mx);
        sc.close();
    }

    static void permute(int pos, boolean[] used, int[] perm, int[] a, int[] b) {
        if (pos == 6) {
            // Compute sum for this permutation
            int[] ta = a.clone();
            int[] tb = b.clone();
            int sum = 0;
            for (int idx : perm) {
                int ai = pairings[idx][0];
                int bi = pairings[idx][1];
                int t = Math.min(ta[ai], tb[bi]);
                ta[ai] -= t;
                tb[bi] -= t;
                sum += t;
            }
            if (sum > maxSum) maxSum = sum;
            return;
        }
        for (int i = 0; i < 6; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[pos] = i;
                permute(pos + 1, used, perm, a, b);
                used[i] = false;
            }
        }
    }
}

