public class Main {
    public static void main(String[] args) {
        solve();
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        List<Integer> list = new ArrayList<>();
        while (sc.hasNextInt()) {
            list.add(sc.nextInt());
        }
        if (list.isEmpty()) {
            return;
        }
        int n = list.get(0);
        int a1 = list.get(1);
        int a2 = list.get(2);
        int a3 = list.get(3);
        int b1 = list.get(4);
        int b2 = list.get(5);
        int b3 = list.get(6);

        int mx = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);

        List<int[]> perms = new ArrayList<>();
        int[] initial = {1,2,3,4,5,6};
        permute(initial, 0, perms);

        int temp = 0;
        for (int[] perm : perms) {
            int ta1 = a1, ta2 = a2, ta3 = a3;
            int tb1 = b1, tb2 = b2, tb3 = b3;
            int tmx = 0;
            for (int el : perm) {
                int t1;
                switch (el) {
                    case 1:
                        t1 = Math.min(ta1, tb1);
                        ta1 -= t1; tb1 -= t1; tmx += t1;
                        break;
                    case 2:
                        t1 = Math.min(ta1, tb3);
                        ta1 -= t1; tb3 -= t1; tmx += t1;
                        break;
                    case 3:
                        t1 = Math.min(ta2, tb2);
                        ta2 -= t1; tb2 -= t1; tmx += t1;
                        break;
                    case 4:
                        t1 = Math.min(ta2, tb1);
                        tb1 -= t1; ta2 -= t1; tmx += t1;
                        break;
                    case 5:
                        t1 = Math.min(ta3, tb3);
                        ta3 -= t1; tb3 -= t1; tmx += t1;
                        break;
                    case 6:
                        t1 = Math.min(ta3, tb2);
                        tb2 -= t1; ta3 -= t1; tmx += t1;
                        break;
                }
            }
            temp = Math.max(temp, tmx);
        }

        System.out.println((n - temp) + " " + mx);
    }

    static void permute(int[] arr, int k, List<int[]> list) {
        if (k == arr.length) {
            list.add(arr.clone());
            return;
        }
        for (int i = k; i < arr.length; i++) {
            swap(arr, k, i);
            permute(arr, k + 1, list);
            swap(arr, k, i);
        }
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

