public class Main {
    static final long INF = (long)1e19;
    static final int MOD = (int)1e9 + 7;
    static final double EPS = 1e-10;

    static class Dinic {
        static final long INF = (long)1e18;
        int n;
        List<List<Edge>> links;
        int[] depth;
        int[] progress;
        List<int[]> pos; // each int[] = {from, index in links[from]}

        Dinic(int n) {
            this.n = n;
            links = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                links.add(new ArrayList<>());
            }
            depth = null;
            progress = null;
            pos = new ArrayList<>();
        }

        Dinic copy() {
            Dinic res = new Dinic(n);
            for (int i = 0; i < n; i++) {
                for (Edge e : links.get(i)) {
                    res.links.get(i).add(new Edge(e.cap, e.to, e.rev));
                }
            }
            for (int[] p : pos) {
                res.pos.add(new int[]{p[0], p[1]});
            }
            return res;
        }

        void addEdge(int from, int to, long cap) {
            pos.add(new int[]{from, links.get(from).size()});
            links.get(from).add(new Edge(cap, to, links.get(to).size()));
            links.get(to).add(new Edge(0, from, links.get(from).size() - 1));
        }

        void bfs(int s) {
            depth = new int[n];
            Arrays.fill(depth, -1);
            depth[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : links.get(v)) {
                    if (e.cap > 0 && depth[e.to] < 0) {
                        depth[e.to] = depth[v] + 1;
                        q.add(e.to);
                    }
                }
            }
        }

        long dfs(int v, int t, long flow) {
            if (v == t) return flow;
            List<Edge> linksV = links.get(v);
            for (int i = progress[v]; i < linksV.size(); i++) {
                progress[v] = i;
                Edge e = linksV.get(i);
                if (e.cap == 0 || depth[v] >= depth[e.to]) continue;
                long d = dfs(e.to, t, Math.min(flow, e.cap));
                if (d == 0) continue;
                e.cap -= d;
                links.get(e.to).get(e.rev).cap += d;
                return d;
            }
            return 0;
        }

        long flow(int s, int t) {
            long flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) return flow;
                progress = new int[n];
                long currentFlow = dfs(s, t, INF);
                while (currentFlow > 0) {
                    flow += currentFlow;
                    currentFlow = dfs(s, t, INF);
                }
            }
        }

        int[] getEdge(int i) {
            int[] p = pos.get(i);
            Edge e = links.get(p[0]).get(p[1]);
            Edge re = links.get(e.to).get(e.rev);
            // from, to, cap, flow
            return new int[]{p[0], e.to, (int)(e.cap + re.cap), (int)re.cap};
        }

        List<int[]> getEdges() {
            List<int[]> res = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                res.add(getEdge(i));
            }
            return res;
        }

        static class Edge {
            long cap;
            int to;
            int rev;
            Edge(long cap, int to, int rev) {
                this.cap = cap;
                this.to = to;
                this.rev = rev;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = 3;
        long[] A = new long[M];
        long[] B = new long[M];
        for (int i = 0; i < M; i++) A[i] = sc.nextLong();
        for (int i = 0; i < M; i++) B[i] = sc.nextLong();

        long ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i+1)%M]);
        }

        long ans2 = 0;
        Dinic dinic = new Dinic(2*M+2);
        int s = 2*M;
        int t = 2*M + 1;
        for (int i = 0; i < M; i++) {
            // s to Alice
            dinic.addEdge(s, i, N);
            // Bob to t
            dinic.addEdge(M+i, t, B[i]);
            // draw
            dinic.addEdge(i, M+i, A[i]);
            // Alice lose
            dinic.addEdge(i, M + (i-1+M)%M, A[i]);
        }
        ans2 = N - dinic.flow(s, t);

        System.out.println(ans2 + " " + ans1);
    }
