        int best = Integer.MAX_VALUE;
        int totalMasks = 1 << (2 * M);
        for (int mask = 0; mask < totalMasks; mask++) {
            int[] x = new int[M];
            int[] y = new int[M];
            for (int i = 0; i < M; i++) {
                x[i] = (mask >> i) & 1;
                y[i] = (mask >> (M + i)) & 1;
            }

            int cut = 0;
            for (int i = 0; i < M; i++) {
                if (x[i] == 0) {
                    cut += N;
                }
                if (x[i] == 1 && y[i] == 0) {
                    cut += A[i];
                }
                if (x[i] == 1 && y[(i - 1 + M) % M] == 0) {
                    cut += A[i];
                }
                if (y[i] == 1) {
                    cut += B[i];
                }
            }

            if (cut < best) {
                best = cut;
            }
        }

        System.out.println((N - best) + " " + ans1);
        sc.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Dinic {
        static final long INF = (long) 1e18;
        int n;
        int[] head;
        ArrayList<Integer> to;
        ArrayList<Long> cap;
        ArrayList<Integer> nxt;
        int[] level;
        int[] it;

        Dinic(int n) {
            this.n = n;
            head = new int[n];
            Arrays.fill(head, -1);
            to = new ArrayList<>();
            cap = new ArrayList<>();
            nxt = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, long capacity) {
            int idx = this.to.size();

            this.to.add(to);
            this.cap.add(capacity);
            this.nxt.add(head[fr]);
            head[fr] = idx;

            this.to.add(fr);
            this.cap.add(0L);
            this.nxt.add(head[to]);
            head[to] = idx + 1;
        }

        void bfs(int s) {
            Arrays.fill(level, -1);
            level[s] = 0;
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(s);

            while (!q.isEmpty()) {
                int v = q.poll();
                int e = head[v];
                while (e != -1) {
                    if (cap.get(e) > 0 && level[to.get(e)] < 0) {
                        level[to.get(e)] = level[v] + 1;
                        q.add(to.get(e));
                    }
                    e = nxt.get(e);
                }
            }
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            int e = it[v];
            while (e != -1) {
                if (cap.get(e) > 0 && level[v] < level[to.get(e)]) {
                    long d = dfs(to.get(e), t, Math.min(f, cap.get(e)));
                    if (d > 0) {
                        cap.set(e, cap.get(e) - d);
                        cap.set(e ^ 1, cap.get(e ^ 1) + d);
                        return d;
                    }
                }
                e = nxt.get(e);
                it[v] = e;
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long ans = 0;
            while (true) {
                bfs(s);
                if (level[t] < 0) return ans;
                it = Arrays.copyOf(head, head.length);
                while (true) {
                    long f = dfs(s, t, INF);
                    if (f == 0) break;
                    ans += f;
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int M = 3;
        int[] A = readArr(br);
        int[] B = readArr(br);

        long ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i + 1) % M]);
        }

        Dinic din = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;

        for (int i = 0; i < M; i++) {
            din.addEdge(s, i, N);
            din.addEdge(M + i, t, B[i]);
            din.addEdge(i, M + i, A[i]);
            din.addEdge(i, M + (i - 1 + M) % M, A[i]);
        }

        long flow = din.maxFlow(s, t);
        System.out.println((N - flow) + " " + ans1);
    }

    static int[] readArr(BufferedReader br) throws IOException {
        String[] parts = br.readLine().split(" ");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }
}

