public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.close();

        int size = 2 * n + 1;
        int[] c = new int[size];
        c[n] = 1; // all others are 0 by default

        for (int i = n - 1; i >= 1; i--) {
            c[i] = (2 * c[i + 1]) % m;
            int maxJ = n / i;
            for (int j = 2; j <= maxJ; j++) {
                int add = (c[i * j] - c[(i + 1) * j]) % m;
                c[i] = (c[i] + add) % m;
                if (c[i] < 0) c[i] += m;
            }
        }

        int result = (c[1] - c[2]) % m;
        if (result < 0) result += m;
        System.out.println(result);
    }
}

