        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        int[] mem = new int[n + 1];
        mem[1] = 1;
        long cum = 1; // cumulative sum modulo mod

        for (int i = 2; i <= n; i++) {
            int sq = isqrt(i) + 1;
            long cur = cum;

            // d from 2 to floor(sqrt(i))
            for (int d = 2; d < sq; d++) {
                cur = (cur + mem[i / d]) % mod;
            }

            int be = i;
            int limit = i / sq;
            for (int j = 1; j <= limit; j++) {
                int nxt = i / (j + 1);
                cur = (cur + (long)(be - nxt) * mem[j]) % mod;
                be = nxt;
            }

            cum = (cum + cur) % mod;
            mem[i] = (int)cur;
        }

        System.out.println(mem[n]);
    }

    // integer square root (floor)
    private static int isqrt(int x) {
        int r = (int)Math.sqrt(x);
        // adjust due to floating point inaccuracies
        while ((r + 1) * (r + 1) <= x) {
            r++;
        }
        while (r * r > x) {
            r--;
        }
        return r;
    }
}

