public class Main {
    static int isqrt(int x) {
        if (x <= 1) return x;
        int lo = 1, hi = x;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (mid <= x / mid) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return hi;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        long[] mem = new long[n + 1];
        if (n >= 1) {
            mem[1] = 1;
            long pref = 1;
            for (int i = 2; i <= n; i++) {
                int sq = isqrt(i) + 1;
                long term1 = 0;
                for (int d = 2; d < sq; d++) {
                    term1 = (term1 + mem[i / d]) % mod;
                }
                long term2 = 0;
                int limit = i / sq;
                for (int k = 1; k <= limit; k++) {
                    long diff = i / k - i / (k + 1);
                    term2 = (term2 + (diff % mod) * mem[k]) % mod;
                }
                long cur = (pref + term1 + term2) % mod;
                pref = (pref + cur) % mod;
                mem[i] = cur;
            }
            System.out.println(mem[n]);
