            int sq = (int) Math.sqrt(i) + 1;
            long cur = su;

            for (int f = 2; f < sq; f++) {
                cur = add(cur, mem.get(i / f), mod);
            }

            int be = i;
            int limit = i / sq;
            for (int j = 1; j <= limit; j++) {
                int nxt = i / (j + 1);
                cur = add(cur, mult(be - nxt, mem.get(j), mod), mod);
                be = nxt;
            }

            su = add(su, cur, mod);
            mem.add(cur);
        }
        System.out.println(mem.get(mem.size() - 1));
    }
}

