import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = 1;
        final long M = 1000000007L;
        for (int t = 0; t < T; t++) {
            process(scanner, M);
        }
        scanner.close();
    }

    private static void process(Scanner scanner, long M) {
        int P = scanner.nextInt();
        int K = scanner.nextInt();
        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (K * x) % P;
        }

        if (K == 0) {
            System.out.println(powMod(P, P - 1, M));
            return;
        }
        if (K == 1) {
            System.out.println(powMod(P, P, M));
            return;
        }

        int[] f = new int[P];
        int[] c = new int[P];
        long ans = 1;
        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;

            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }
            c[cnt]++;
        }

        for (int i = 2; i < P; i++) {
            if (c[i] != 0) {
                long cnt = (long) i * c[i] + 1;
                ans = (ans * powMod(cnt, c[i], M)) % M;
            }
        }
        System.out.println(ans);
    }

    private static long powMod(long base, int exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

