        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;
        String[] parts = line.trim().split(" ");
        int P = Integer.parseInt(parts[0]);
        int K = Integer.parseInt(parts[1]);

        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (int)(((long)K * x) % P);
        }

        if (K == 0) {
            System.out.println(powMod(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            System.out.println(powMod(P, P, MOD));
            return;
        }

        int[] visited = new int[P];
        int[] counts = new int[P];
        long ans = 1;

        for (int start = 0; start < P; start++) {
            if (visited[start] != 0) continue;
            int length = 1;
            int node = start;
            visited[node] = 1;
            while (visited[k[node]] == 0) {
                node = k[node];
                visited[node] = 1;
                length++;
            }
            counts[length]++;
        }

        for (int i = 2; i < P; i++) {
            if (counts[i] > 0) {
                long factor = (long)i * counts[i] + 1;
                ans = (ans * powMod(factor, counts[i], MOD)) % MOD;
            }
        }

        System.out.println(ans);
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

