        int[] k = new int[P];
        for (int i = 0; i < P; i++) {
            k[i] = (int)(((long)K * i) % P);
        }

        boolean[] seen = new boolean[P];
        int[] cnt = new int[P]; // cnt[length] counts cycles of that length

        for (int i = 0; i < P; i++) {
