        if (K == 0) {
            BigInteger base = BigInteger.valueOf(P);
            BigInteger exp = BigInteger.valueOf(P - 1);
            BigInteger mod = BigInteger.valueOf(M);
            BigInteger result = base.modPow(exp, mod);
            System.out.println(result.toString());
            return;
