import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    static boolean isGood(ArrayList<Integer> f, int p, int k) {
        for (int i = 0; i < p; i++) {
            if (f.get((k * i) % p) != (k * f.get(i)) % p) {
                return false;
            }
        }
        return true;
    }

    static long gen(ArrayList<Integer> f, int p, int k, int i) {
        if (i == p) {
            return isGood(f, p, k) ? 1 : 0;
        } else {
            long ans = 0;
            for (int j = 0; j < p; j++) {
                f.add(j);
                ans += gen(f, p, k, i + 1);
                f.remove(f.size() - 1);
            }
            return ans;
        }
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long solve(int p, int k) {
        int num = 0;
        Set<Integer> used = new HashSet<>();
        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
            }
            int i = j;
            while (!used.contains(i)) {
                used.add(i);
                i = (i * k) % p;
            }
        }
        long exponent = num - (k != 1 ? 1 : 0);
        return modPow(p, exponent, MOD);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        // System.out.println(gen(new ArrayList<>(), p, k, 0));
        System.out.println(solve(p, k));
        sc.close();
    }
}

