import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    private static final int M = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) {
            return;
        }
        StringTokenizer st = new StringTokenizer(line);
        int P = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] k = new int[P];
        for (int i = 0; i < P; i++) {
            k[i] = (int)(((long)K * i) % P);
        }

        if (K == 0) {
            System.out.println(modPow(P, P - 1, M));
            return;
        }

        boolean[] f = new boolean[P];
        int[] c = new int[P];
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i]) continue;
            int length = 1;
            int pos = i;
            f[pos] = true;
            while (true) {
                int nxt = k[pos];
                if (f[nxt]) break;
                f[nxt] = true;
                pos = nxt;
                length++;
            }
            c[length]++;
        }

        for (int size = 1; size < P; size++) {
            if (c[size] != 0) {
                long mult = (long)size * c[size];
                if (size > 1) {
                    mult += c[1];
                }
                ans = (ans * modPow(mult, c[size], M)) % M;
            }
        }

        System.out.println(ans);
    }

    private static long modPow(long base, int exp, int mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

