public class Main {
    static final long MOD = 1000000007L;

    static long powMod(long a, long e, long mod) {
        long res = 1;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            e >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // int T = 1; // Only one test case
        int P = scanner.nextInt();
        int K = scanner.nextInt();
        scanner.close();

        // k[x] = K * x % P
        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (K * x) % P;
        }

        if (K == 0) {
            System.out.println(powMod(P, P - 1, MOD));
            return;
        }

        int[] f = new int[P]; // visited flag
        int[] c = new int[P]; // counts of cycle lengths
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;
            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }
            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                long cnt = (long) i * c[i] + (i > 1 ? 1 : 0);
                ans = (ans * powMod(cnt, c[i], MOD)) % MOD;
            }
        }

        System.out.println(ans);
    }
}

