public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long order = orderOfK(p, k);
        BigInteger result = BigInteger.valueOf(p).modPow(BigInteger.valueOf(order), BigInteger.valueOf(MOD));
        System.out.println(result);
    }

    static long orderOfK(long p, long k) {
        if (k == 0) {
            return p - 1;
        }
        if (k == 1) {
            return p;
        }
        long n = p - 1;
        // Find all divisors of n
        List<Long> divs = new ArrayList<>();
        long sqrt = (long) Math.sqrt(n);
        for (long d = 1; d <= sqrt; d++) {
            if (n % d == 0) {
                divs.add(d);
                long other = n / d;
                if (other != d) {
                    divs.add(other);
                }
            }
        }
        Collections.sort(divs);
        for (long z : divs) {
            if (BigInteger.valueOf(k).modPow(BigInteger.valueOf(z), BigInteger.valueOf(p)).equals(BigInteger.ONE)) {
                return (p - 1) / z;
            }
        }
        return -1; // Should never happen
    }
}

