        BigInteger n = sc.nextBigInteger();
        BigInteger one = BigInteger.ONE;
        BigInteger two = BigInteger.valueOf(2);
        BigInteger powH = two.pow(h);

        BigInteger m;
        if (n.compareTo(BigInteger.ZERO) <= 0) {
            m = BigInteger.ZERO;
