        int i = 0;
        char prev = '1';
        int len = bits.length();
        int idx = 0;
        while (idx < len) {
            char ch = bits.charAt(idx);
            int k = 0;
            while (idx < len && bits.charAt(idx) == ch) {
                k++;
                idx++;
            }
            BigInteger term;
            if (ch == prev) {
                BigInteger term1 = two.pow(h - i + 1);
                BigInteger term2 = two.pow(h - i - k + 1);
                term = term1.subtract(term2);
