import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        solve();
    }

    private static ArrayList<BigInteger> make_path(BigInteger x) {
        ArrayList<BigInteger> path = new ArrayList<>();
        while (x.compareTo(BigInteger.ONE) >= 0) {
            path.add(x);
            if (x.equals(BigInteger.ONE)) break;
            x = x.divide(BigInteger.valueOf(2));
        }
        // The original recursion returns [x] + make_path(x//2) for x>1, so path is from x down to 1.
        // Our loop builds from x down to 1, but we need the order as in recursion: first element is x, then x//2, etc.
        // The loop adds x, then x//2, etc., so it's correct.
        return path;
    }

    private static void solve() {
        Scanner sc = new Scanner(System.in);
        String[] parts = sc.nextLine().split(" ");
        BigInteger hBig = new BigInteger(parts[0]);
        BigInteger nBig = new BigInteger(parts[1]);
        int h = hBig.intValue(); // h is used as int for depth and shifts
        BigInteger n = nBig;

        BigInteger target = n.add(BigInteger.ONE.shiftLeft(h).subtract(BigInteger.ONE));
        ArrayList<BigInteger> anc = make_path(target);

        BigInteger ans = BigInteger.ZERO;
        BigInteger cur = BigInteger.ONE;
        boolean right = false;
        int depth = h;

        while (!cur.equals(target)) {
            ArrayList<BigInteger> temp = new ArrayList<>();
            for (int k = 0; k < depth; k++) {
                temp.add(cur);
                if (right) {
                    cur = cur.shiftLeft(1).or(BigInteger.ONE);
                } else {
                    cur = cur.shiftLeft(1);
                }
                right = !right;
            }
            if (cur.equals(target)) {
                ans = ans.add(BigInteger.valueOf(depth));
                break;
            }
            temp.add(cur);
            Collections.reverse(temp);

            for (int i = 1; i <= depth; i++) {
                if (anc.get(i).equals(temp.get(i))) {
                    ans = ans.add(BigInteger.ONE.shiftLeft(i).subtract(BigInteger.ONE).add(BigInteger.valueOf(depth - i + 1)));
                    depth = i - 1;
                    cur = temp.get(i - 1);
                    if (cur.equals(temp.get(i).shiftLeft(1))) {
                        cur = temp.get(i).shiftLeft(1).or(BigInteger.ONE);
                        right = false;
                    } else {
                        cur = temp.get(i).shiftLeft(1);
                        right = true;
                    }
                    break;
                }
            }
        }

        System.out.println(ans);
    }
}

