        if (level == h) {
            return 0;
        }
        int cur = (int)((n >> (h - 1 - level)) & 1);
        int s_bit;
        if (level == 0) {
            s_bit = cur;
        } else {
            s_bit = (prev == 0) ? (1 - cur) : cur;
        }
        long ct = 1;
        if (s_bit == 1) {
            ct += (1L << (h - level)) - 1;
        }
        return ct + dfs(level + 1, cur);
    }
}

