import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine().replaceAll("\\s+$", ""); // rstrip trailing whitespace

        // Handle strings with length less than 2 (same as Python behavior for length 1)
        if (s.length() < 2) {
            System.out.println(s);
            return;
        }

        // Inner part (excluding first and last characters)
        StringBuilder inner = new StringBuilder(s.substring(1, s.length() - 1));

        // Replace all occurrences of "dot" with "."
        int i = 0;
        while (i < inner.length() - 2) {
            if (inner.substring(i, i + 3).equals("dot")) {
                inner.replace(i, i + 3, ".");
                i += 1; // after replacement, the new '.' is at position i, next char at i+1
            } else {
                i++;
            }
        }

        // Replace first occurrence of "at" with "@"
        boolean found = false;
        i = 0;
        while (i < inner.length() - 1) {
            if (!found && inner.substring(i, i + 2).equals("at")) {
                inner.replace(i, i + 2, "@");
                found = true;
                i += 1;
            } else {
                i++;
            }
        }

        // Reconstruct the string
        String result = s.charAt(0) + inner.toString() + s.charAt(s.length() - 1);
        System.out.println(result);
    }
}

