import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        System.out.println(process(input));
        scanner.close();
    }

    public static String process(String s) {
        // replace first 'at' with '@'
        int idx = s.indexOf("at");
        if (idx != -1) {
            s = s.substring(0, idx) + "@" + s.substring(idx + 2);
        }
        // replace all 'dot' with '.' one at a time
        while (s.contains("dot")) {
            int dotIdx = s.indexOf("dot");
            if (dotIdx != -1) {
                s = s.substring(0, dotIdx) + "." + s.substring(dotIdx + 3);
            }
        }
        // if first character is '.', replace with 'dot'
        if (!s.isEmpty() && s.charAt(0) == '.') {
            s = "dot" + s.substring(1);
        }
        // if first character is '@', handle special case
        if (!s.isEmpty() && s.charAt(0) == '@') {
            int idx2 = s.indexOf("at");
            if (idx2 != -1) {
                s = s.substring(0, idx2) + "@" + s.substring(idx2 + 2);
            }
            s = "at" + s.substring(1);
        }
        // if last character is '.', replace with 'dot'
        if (!s.isEmpty() && s.charAt(s.length() - 1) == '.') {
            s = s.substring(0, s.length() - 1) + "dot";
        }
        return s;
    }
}

