            // Second pass: only replace first "at" with "@"
            StringBuilder res2 = new StringBuilder();
            int j = 0;
            boolean firstAtDone2 = false;
            while (j < s.length()) {
                if (!firstAtDone2 && j + 2 <= s.length() && s.substring(j, j + 2).equals("at")) {
                    res2.append('@');
                    j += 2;
                    firstAtDone2 = true;
                } else {
                    res2.append(s.charAt(j));
                    j++;
                }
            }
            s = res2.toString();
            s = "at" + s.substring(1);
        }

        // Handle last character
        if (!s.isEmpty() && s.charAt(s.length() - 1) == '.') {
            s = s.substring(0, s.length() - 1) + "dot";
        }

        System.out.println(s);
        scanner.close();
    }
}

