import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();

        // Replace "dot" with "." repeatedly in interior (excluding first and last characters)
        Pattern dotPattern = Pattern.compile("dot");
        while (true) {
            // Search in substring s[1:-1]
            String interior = s.substring(1, s.length() - 1);
            Matcher matcher = dotPattern.matcher(interior);
            if (!matcher.find()) {
                break;
            }
            int a = matcher.start(); // index in interior
            // Original index = a + 1
            s = s.substring(0, a + 1) + "." + s.substring(a + 4);
        }

        // Replace "at" with "@" once in interior
        Pattern atPattern = Pattern.compile("at");
        String interior = s.substring(1, s.length() - 1);
        Matcher matcher = atPattern.matcher(interior);
        if (matcher.find()) {
            int a = matcher.start();
            s = s.substring(0, a + 1) + "@" + s.substring(a + 3);
        } else {
            // Mimic Python behavior when no match: a = -1, then s[:0] + '@' + s[2:]
            // In Python, s[2:] returns empty if length < 2, so we handle safely.
            String suffix = (s.length() > 2) ? s.substring(2) : "";
            s = "@" + suffix;
        }

        System.out.println(s);
    }
}

