public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        System.out.println(process(input));
        scanner.close();
    }

    public static String process(String s) {
        StringBuilder sb = new StringBuilder(s);
        // Replace "dot" with "." but only within indices 1 to len-2 (exclusive of first and last characters)
        while (true) {
            int idx = sb.indexOf("dot", 1); // search from index 1
            if (idx == -1) {
                break;
            }
            // Check if the "dot" is completely within the range [1, len-2]
            // i.e., start index >= 1 and end index (idx+2) <= len-2
            if (idx >= 1 && idx + 2 <= sb.length() - 2) {
                sb.replace(idx, idx + 3, ".");
            } else {
                break;
            }
        }
        // Replace first occurrence of "at" with "@" but only if it starts at index >= 1
        int idx = sb.indexOf("at", 1);
        if (idx != -1) {
            sb.replace(idx, idx + 2, "@");
        }
        return sb.toString();
    }
}

import java.util.Scanner;

public class ReplaceInterior {
    public static String replaceInterior(String s) {
        // Check if 'dot' is in the interior (excluding first and last characters)
        if (s.length() < 3) {
            return s;
        }
        String interior = s.substring(1, s.length() - 1);
        if (!interior.contains("dot")) {
            return s;
        }
        // Find the first occurrence of 'dot' in the interior
        int idxInInterior = interior.indexOf("dot");
        int pos = idxInInterior + 1; // absolute position in original string
        // Replace 'dot' with '.' at that position
        String newS = s.substring(0, pos) + "." + s.substring(pos + 3);
        return replaceInterior(newS);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String string = scanner.nextLine();
        string = replaceInterior(string);
        // Check if 'at' appears in the substring starting from index 1
        if (string.length() > 1) {
            String suffix = string.substring(1);
            if (suffix.contains("at")) {
                int idxInSuffix = suffix.indexOf("at");
                int pos = idxInSuffix + 1; // absolute position
                string = string.substring(0, pos) + "@" + string.substring(pos + 2);
            }
        }
        System.out.println(string);
        scanner.close();
    }
}

