import java.util.Scanner;

public class Transform {
    public static String transform(String s) {
        // Process 'at' rule: first occurrence stays if at start, else replaced
        int idx = s.indexOf("at");
        if (idx == 0) {
            // first 'at' at beginning: replace the next 'at' in the remainder
            String rest = s.substring(2);
            rest = rest.replaceFirst("at", "@");
            s = s.substring(0, 2) + rest;
        } else if (idx > 0) {
            // replace first occurrence
            s = s.substring(0, idx) + "@" + s.substring(idx + 2);
        }
        // else no 'at' at all

        // Process 'dot' rule: replace all, then fix borders
        s = s.replace("dot", ".");
        if (!s.isEmpty() && s.charAt(0) == '.') {
            s = "dot" + s.substring(1);
        }
        if (!s.isEmpty() && s.charAt(s.length() - 1) == '.') {
            s = s.substring(0, s.length() - 1) + "dot";
        }
        return s;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        System.out.println(transform(input));
        scanner.close();
    }
}

