public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        List<Character> s = new ArrayList<>();
        for (char c : input.toCharArray()) {
            s.add(c);
        }
        int n = s.size();
        int i = 0;
        boolean firstAtHandled = false;
        while (i < n - 1) {
            if (s.get(i) == 'a' && s.get(i + 1) == 't') {
                if (!firstAtHandled) {
                    if (i == 0) {
                        firstAtHandled = true;
                        i += 2;
                        continue;
                    } else {
                        s.set(i, '@');
                        s.remove(i + 1);
                        n--;
                        firstAtHandled = true;
                        i++;
                        continue;
                    }
                } else {
                    break;
                }
            }
            i++;
        }

        i = 0;
        while (i < n - 2) {
            if (s.get(i) == 'd' && s.get(i + 1) == 'o' && s.get(i + 2) == 't') {
                s.set(i, '.');
                s.remove(i + 1);
                s.remove(i + 1); // after first removal, original i+2 becomes i+1
                n -= 2;
                i++;
            } else {
                i++;
            }
        }

        if (!s.isEmpty() && s.get(0) == '.') {
            s.set(0, 'd');
            s.add(1, 'o');
            s.add(2, 't');
            n += 2;
        }
        if (!s.isEmpty() && s.get(s.size() - 1) == '.') {
            s.set(s.size() - 1, 't');
            s.add(s.size() - 1, 'o');
            s.add(s.size() - 1, 'd');
            n += 2;
        }

        StringBuilder sb = new StringBuilder();
        for (char c : s) {
            sb.append(c);
        }
        System.out.println(sb.toString());
    }
}

