            # 'at' is at the start
            # Replace the next 'at' in the remainder (if any)
            if 'at' in parts[1]:
                second_parts = parts[1].split('at', 1)
                s = 'at' + second_parts[0] + '@' + second_parts[1]
            else:
                # only one 'at' at start, keep it
                s = 'at' + parts[1]
        else:
            # first 'at' not at start, replace it
            s = parts[0] + '@' + parts[1]

    # Process 'dot' using split and join
    if 'dot' in s:
        segments = s.split('dot')
        s = '.'.join(segments)
        # Handle border cases
        if s[0] == '.':
            s = 'dot' + s[1:]
        if s[-1] == '.':
            s = s[:-1] + 'dot'

    sys.stdout.write(s + '\n')

