        }
        sc.close();

        int half = n / 2 + n % 2; // ceil(n/2)
        ArrayList<Integer> b = sumsFrom(0, half, a, m);
        Collections.sort(b);

        int otv = 0;
        ArrayList<Integer> secondSums = sumsFrom(half, n / 2, a, m);
        for (int second : secondSums) {
            int target = m - second - 1;
            int pos = bisectLeft(b, target);
            int t2;
            if (pos < b.size()) {
                t2 = b.get(pos);
                if (t2 > target) {
                    if (pos - 1 >= 0) {
                        t2 = b.get(pos - 1);
                    }
                }
            } else {
                t2 = b.get(b.size() - 1);
            }
            int candidate1 = (second + t2) % m;
            int candidate2 = (second + b.get(b.size() - 1)) % m;
            otv = Math.max(otv, Math.max(candidate1, candidate2));
        }

        System.out.println(otv % m);
    }

    // Generate all subset sums modulo m from at most 20 elements starting at index start
    static ArrayList<Integer> sumsFrom(int start, int cnt, int[] a, int m) {
        int upto = Math.min(cnt, 20);
        ArrayList<Integer> result = new ArrayList<>();
        int limit = 1 << upto;
        for (int mask = 0; mask < limit; mask++) {
            long total = 0;
            for (int i = 0; i < upto; i++) {
                if ((mask & (1 << i)) != 0) {
                    total += a[start + i];
                }
            }
            result.add((int)(total % m));
        }
        return result;
    }

    // Returns the index of the first element >= key (insertion point)
    static int bisectLeft(ArrayList<Integer> list, int key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

