                t2 = b.get(k);
                if (t2 > target) {
                    if (k - 1 >= 0) {
                        t2 = b.get(k - 1);
                    }
                }
            } else {
                t2 = b.get(b.size() - 1);
            }
            int last = b.get(b.size() - 1);
            otv = Math.max(otv, (int)((t + t2) % m));
            otv = Math.max(otv, (int)((t + last) % m));
        }
        System.out.println(otv % m);
    }

    private static List<Integer> gen(int[] a, int pos, int cnt, int m) {
        List<Integer> out = new ArrayList<>();
        int limit = 1 << cnt;
        for (int mask = 0; mask < limit; mask++) {
            int x = mask;
            long s = 0;
            int bit = 0;
            while (bit < 20) {
                if ((x & 1) == 1) {
                    s += a[pos + bit];
                }
                x >>= 1;
                bit++;
            }
            out.add((int)(s % m));
        }
        return out;
    }
}

