        }
        int half = n / 2 + n % 2;
        int[] b = calc(a, 0, half, m);
        Arrays.sort(b);
        int otv = 0;
        int[] c = calc(a, half, n / 2, m);
        for (int t : c) {
            int target = m - t - 1;
            int idx = bisectRight(b, target) - 1;
            int best;
            if (idx < 0) {
