            otv = Math.max(otv, (t + b[b.length - 1]) % m);
        }
        System.out.println(otv % m);
    }

    static int[] calc(int[] a, int start, int cnt, int m) {
        int upto = Math.min(cnt, 20);
        int size = 1 << upto;
        int[] res = new int[size];
        for (int mask = 0; mask < size; mask++) {
            int sum = 0;
            for (int i = 0; i < upto; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[start + i];
                }
            }
            res[mask] = sum % m;
        }
        return res;
    }

    static int bisectRight(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
