            }
            // j is the insertion point, so the largest element less than target is at j-1
            if (j > 0) {
                ans = Math.max(ans, a1[j - 1] + i);
            } else {
                // if j == 0, then all elements are >= target, so the largest element is the last one
                ans = Math.max(ans, a1[a1.length - 1] + i);
            }
        }
        System.out.println(ans);
    }

    private static long[] subsetSums(long[] arr, int start, int end, long mod) {
        int len = end - start;
        int total = 1 << len;
        long[] sums = new long[total];
        for (int mask = 0; mask < total; mask++) {
            long sum = 0;
            for (int i = 0; i < len; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[start + i];
                }
            }
            sums[mask] = sum % mod;
        }
        return sums;
    }
