        List<Integer> right = new ArrayList<>();

        gen(0, mid, 0, m, a, left);
        gen(mid, n, 0, m, a, right);

        // Remove duplicates and sort left
        Set<Integer> leftSet = new TreeSet<>(left);
        left = new ArrayList<>(leftSet);

        int ans = 0;
        for (int val : right) {
            int target = m - val;
            int lo = 0, hi = left.size() - 1;
            int best = -1;
            while (lo <= hi) {
                int midIdx = (lo + hi) / 2;
                if (left.get(midIdx) < target) {
                    best = midIdx;
                    lo = midIdx + 1;
                } else {
                    hi = midIdx - 1;
                }
            }
            if (best != -1) {
                int cand = left.get(best) + val;
                if (cand > ans) {
                    ans = cand;
                }
            }
        }
        System.out.println(ans);
    }

    private static void gen(int start, int end, int cur, int m, int[] a, List<Integer> out) {
        if (start == end) {
            out.add(cur);
            return;
        }
        gen(start + 1, end, (cur + a[start]) % m, m, a, out);
        gen(start + 1, end, cur, m, a, out);
    }
}

