        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        sc.close();

        int n1 = n / 2;
        List<Integer> a1 = subsetSumsMod(Arrays.copyOfRange(a, 0, n1), m);
        List<Integer> a2 = subsetSumsMod(Arrays.copyOfRange(a, n1, n), m);

        Collections.sort(a1);
        int ans = 0;
        for (int i : a2) {
            int target = m - i;
            int j = Collections.binarySearch(a1, target);
            if (j < 0) {
                j = -j - 1; // insertion point
            }
            if (j > 0) {
                int cand = a1.get(j - 1) + i;
                if (cand > ans) {
                    ans = cand;
                }
            }
        }
        System.out.println(ans);
    }

    private static List<Integer> subsetSumsMod(int[] arr, int mod) {
        int n = arr.length;
        Set<Integer> res = new HashSet<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            int s = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) {
                    s = (s + arr[j]) % mod;
                }
            }
            res.add(s);
        }
        return new ArrayList<>(res);
    }
}

