        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        sc.close();

        int n1 = n / 2;

        List<Integer> a1 = genSums(a, 0, n1, m);
        List<Integer> a2 = genSums(a, n1, n, m);

        // Deduplicate and sort a1
        TreeSet<Integer> set = new TreeSet<>(a1);
        a1 = new ArrayList<>(set);

        int ans = 0;
        for (int i : a2) {
            int key = m - i;
            int pos = bisectLeft(a1, key);
            if (pos > 0) {
                int cand = a1.get(pos - 1) + i;
                if (cand > ans) {
                    ans = cand;
                }
            }
        }

        System.out.println(ans);
    }

    private static List<Integer> genSums(int[] a, int start, int end, int m) {
        List<Integer> seq = new ArrayList<>();
        dfs(start, 0, start, end, a, m, seq);
        return seq;
    }

    private static void dfs(int idx, int sum, int start, int end, int[] a, int m, List<Integer> seq) {
        if (idx == end) {
            seq.add(sum);
            return;
        }
        dfs(idx + 1, (sum + a[idx]) % m, start, end, a, m, seq);
        dfs(idx + 1, sum, start, end, a, m, seq);
    }

    private static int bisectLeft(List<Integer> list, int key) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

