        ArrayList<Integer> sums = new ArrayList<>();
        sums.add(0);
        for (int x : arr) {
            ArrayList<Integer> newSums = new ArrayList<>();
            for (int s : sums) {
                newSums.add((s + x) % mod);
                newSums.add(s);
            }
            sums = newSums;
        }
        return sums;
    }
}

