    private static void dfs(int pos, long total, int[] part, int m, List<Integer> res) {
        if (pos == part.length) {
            res.add((int)(total % m));
            return;
        }
        dfs(pos + 1, total, part, m, res);
        dfs(pos + 1, (total + part[pos]) % m, part, m, res);
    }

