            if (cand != -1) {
                int total = (cand + i) % m;
                if (total > ans) {
                    ans = total;
                }
            }
        }
        System.out.println(ans);
    }

    // generate all subset sums modulo m for indices [lo, hi)
    private static List<Integer> gen(int lo, int hi, int[] a, int m) {
        List<Integer> sums = new ArrayList<>();
        sums.add(0);
        for (int idx = lo; idx < hi; idx++) {
            int cur = a[idx];
            List<Integer> newSums = new ArrayList<>();
            for (int s : sums) {
                newSums.add((s + cur) % m);
            }
            sums.addAll(newSums);
        }
        return sums;
    }

    // find the largest element in sorted list that is strictly less than x
    // returns -1 if no such element
    private static int maxLess(List<Integer> list, int x) {
        int idx = Collections.binarySearch(list, x);
        if (idx >= 0) {
            // exact match found, we need the element before it
            if (idx > 0) {
                return list.get(idx - 1);
            } else {
                return -1;
            }
        } else {
            // insertion point = -idx - 1
            int ins = -idx - 1;
            if (ins > 0) {
                return list.get(ins - 1);
            } else {
                return -1;
            }
        }
    }
}

