import java.io.*;
import java.util.*;

public class Main {
    public static HashSet<Integer> subsetSums(int[] arr, int k) {
        HashSet<Integer> sums = new HashSet<>();
        for (int x : arr) {
            x %= k;
            HashSet<Integer> newSums = new HashSet<>();
            for (int y : sums) {
                newSums.add((x + y) % k);
            }
            sums.add(x);
            sums.addAll(newSums);
        }
        return sums;
    }

    // Returns the index of the first element > target (like bisect_right)
    private static int bisectRight(ArrayList<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        if (!st.hasMoreTokens()) return;
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] arr = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken()) % k;
        }

        if (n == 1) {
            System.out.println(arr[0]);
            return;
        }

        int mid = n / 2;
        int[] leftArr = Arrays.copyOfRange(arr, 0, mid);
        int[] rightArr = Arrays.copyOfRange(arr, mid, n);

        HashSet<Integer> leftSet = subsetSums(leftArr, k);
        HashSet<Integer> rightSet = subsetSums(rightArr, k);

        ArrayList<Integer> leftList = new ArrayList<>(leftSet);
        ArrayList<Integer> rightList = new ArrayList<>(rightSet);
        Collections.sort(leftList);
        Collections.sort(rightList);

        int ans = Math.max(leftList.get(leftList.size() - 1), rightList.get(rightList.size() - 1));

        int lastRight = rightList.get(rightList.size() - 1);
        for (int x : leftList) {
            int idx = bisectRight(rightList, k - 1 - x);
            int y = (idx > 0) ? rightList.get(idx - 1) : lastRight;
            ans = Math.max(ans, (x + y) % k);
            ans = Math.max(ans, (x + lastRight) % k);
        }

        System.out.println(ans);
    }
}

