        int mid = n / 2;
        for (int i = 0; i < mid; i++) leftPart.add(arr[i]);
        for (int i = mid; i < n; i++) rightPart.add(arr[i]);

        Set<Integer> leftSet = allSubsetSums(leftPart, k);
        Set<Integer> rightSet = allSubsetSums(rightPart, k);

