            int idx = Collections.binarySearch(R, target);
            int b;
            if (idx >= 0) {
                b = R.get(idx);
            } else {
                int ip = -idx - 1;
                if (ip == 0) {
                    b = R.get(R.size() - 1);
                } else {
                    b = R.get(ip - 1);
