import java.util.*;
import java.util.stream.*;

public class Main {
    static int mod;
    static List<Map<Integer, Integer>>[] memo;

    static int invnum(int[] seq) {
        int N = seq.length;
        int res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    static int solve(int N, int k, int flag) {
        if (memo[N][flag].containsKey(k)) {
            return memo[N][flag].get(k);
        }
        if (N == 1) {
            int res;
            if (flag == 1) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][flag].put(k, res);
            return res;
        }
        int invnum_INF = N * (N - 1) / 2;
        if (k < -invnum_INF - 1) {
            int res = solve(N, -invnum_INF - 1, flag);
            memo[N][flag].put(k, res);
            return res;
        }
        if (k >= invnum_INF) {
            memo[N][flag].put(k, 0);
            return 0;
        }
        long res = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag == 1 && delta > 0) {
                continue;
            }
            int wt = Math.min(N - delta, delta + N);
            res += (long) solve(N - 1, k - delta, (delta == 0 ? 1 : 0) & flag) * wt;
            res %= mod;
        }
        memo[N][flag].put(k, (int)res);
        return (int)res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();
        memo = new List[n + 1][2];
        for (int i = 0; i <= n; i++) {
            memo[i][0] = new HashMap<>();
            memo[i][1] = new HashMap<>();
        }
        int ans = solve(n, 0, 1) % mod;
        System.out.println(ans);
    }
    static int n;
}

