import java.util.*;

public class Main {
    static int mod;
    static Map<Key, Long> memo = new HashMap<>();

    static class Key {
        int N, k;
        boolean flag;
        Key(int N, int k, boolean flag) {
            this.N = N;
            this.k = k;
            this.flag = flag;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key)) return false;
            Key key = (Key) o;
            return N == key.N && k == key.k && flag == key.flag;
        }
        @Override
        public int hashCode() {
            return Objects.hash(N, k, flag);
        }
    }

    static long solve(int N, int k, boolean flag) {
        Key key = new Key(N, k, flag);
        if (memo.containsKey(key)) return memo.get(key);

        if (N == 1) {
            long res;
            if (flag) {
                res = (mod - 1) % mod; // equivalent to -1 mod mod
            } else {
                res = (k < 0) ? 1 : 0;
            }
            memo.put(key, res);
            return res;
        }

        long inv = (long) N * (N - 1) / 2;

        if (k < -inv - 1) {
            long res = solve(N, (int)(-inv - 1), flag);
            memo.put(key, res);
            return res;
        }
        if (k >= inv) {
            memo.put(key, 0L);
            return 0;
        }

        long res = 0;
        for (int d = -N + 1; d < N; d++) {
            if (flag && d > 0) continue;
            long term = solve(N - 1, k - d, (d == 0) && flag);
            long mult = Math.min(N - d, d + N);
            res = (res + term * mult) % mod;
        }
        // ensure non-negative
        if (res < 0) res += mod;
        memo.put(key, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();
        long ans = solve(n, 0, true) % mod;
        if (ans < 0) ans += mod;
        System.out.println(ans);
        sc.close();
    }
}

