        boolean flag;
        Key(int N, int k, boolean flag) {
            this.N = N;
            this.k = k;
            this.flag = flag;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key)) return false;
            Key key = (Key) o;
            return N == key.N && k == key.k && flag == key.flag;
        }
        @Override
        public int hashCode() {
            return Objects.hash(N, k, flag);
        }
    }

    static long calc(int N, int k, boolean flag) {
        Key key = new Key(N, k, flag);
        if (memo.containsKey(key)) return memo.get(key);

        long res;
        if (N == 1) {
            long base = flag ? -1 : (k < 0 ? 1 : 0);
            res = (base % mod + mod) % mod;
        } else {
            int inv = N * (N - 1) / 2;
            if (k < -inv - 1) {
                res = calc(N, -inv - 1, flag);
            } else if (k >= inv) {
                res = 0;
            } else {
                res = 0;
                int start = -N + 1;
                int end = flag ? 0 : N - 1;
                for (int d = start; d <= end; d++) {
                    long term = calc(N - 1, k - d, flag && (d == 0));
                    int multiplier = Math.min(N - d, N + d);
                    res = (res + term * multiplier) % mod;
                }
            }
        }
        memo.put(key, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();
        System.out.println(calc(n, 0, true) % mod);
    }
}

