        int mod = Integer.parseInt(parts[1]);
        System.out.println(solve(n, mod));
    }

    static int solve(int n, int mod) {
        int m = n * (n - 1) / 2;
        int size = 2 * m + 1;
        int[] prev_dp = new int[size];
        int[] prev_dp1 = new int[size];
        prev_dp[m] = 1;

        for (int i = 2; i <= n; i++) {
            int[] P0 = new int[size + 1];
            int[] P1 = new int[size + 1];
            for (int pos = 0; pos < size; pos++) {
                int v = prev_dp[pos];
                P0[pos + 1] = (P0[pos] + v) % mod;
                P1[pos + 1] = (int)((P1[pos] + (long)pos * v) % mod);
            }

            int[] cur_dp = new int[size];
            int lo = m - i * (i - 1) / 2;
            int hi = m + i * (i - 1) / 2;
            int rad = i - 1;

            for (int t = lo; t <= hi; t++) {
                int L = t - rad;
                if (L < 0) L = 0;
                int R = t + rad;
                if (R >= size) R = size - 1;

                int mid = t;
                if (mid > R) mid = R;
                int rstart = t + 1;
                if (rstart < L) rstart = L;

                long left_a = P0[mid + 1] - P0[L];
                long left_ja = P1[mid + 1] - P1[L];
                long right_a, right_ja;
                if (rstart <= R) {
                    right_a = P0[R + 1] - P0[rstart];
                    right_ja = P1[R + 1] - P1[rstart];
