                long S1 = (long)t * left_a - left_ja + right_ja - (long)t * right_a;
                long val = ((long)i * S0 - S1) % mod;
                if (val < 0) val += mod;
                cur_dp[t] = (int)val;
            }

            int[] cur_dp1 = new int[size];
            int lo_old = m - (i - 1) * (i - 2) / 2;
            int hi_old = m + (i - 1) * (i - 2) / 2;

            for (int x = lo_old; x <= hi_old; x++) {
                cur_dp1[x] = (int)((long)prev_dp1[x] * i % mod);
            }

            for (int x = lo_old; x <= hi_old; x++) {
                int v = prev_dp[x];
                if (v != 0) {
                    for (int d = 1; d < i; d++) {
                        int y = x - d;
                        cur_dp1[y] = (int)((cur_dp1[y] + (long)v * (i - d)) % mod);
                    }
                }
            }

            prev_dp = cur_dp;
            prev_dp1 = cur_dp1;
        }

        long sum = 0;
        for (int idx = m + 1; idx < size; idx++) {
            sum = (sum + prev_dp1[idx]) % mod;
        }
        return (int)sum;
    }
