public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static long factorial(long n) {
        long result = 1;
        for (long i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    static long A(long n, long k) {
        return factorial(n) / factorial(n - k);
    }

    public static void main(String[] args) throws Exception {
        st = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());
        if (n == 1) {
            System.out.println(0);
            return;
        }
        // z is a list of integers, initially [1]
        ArrayList<Integer> z = new ArrayList<>();
        z.add(1);
        long aaa = 0;
        for (int i = 2; i <= n; i++) {
            int size = i * i / 2;
            ArrayList<Integer> nz = new ArrayList<>(Collections.nCopies(size, 0));
            for (int j = 0; j < z.size(); j++) {
                for (int k = 0; k < i; k++) {
                    if (z.get(j) > 0) {
                        int index = i - k - 1 + j;
                        if (index < nz.size()) {
                            nz.set(index, nz.get(index) + z.get(j));
                        }
                    }
                }
            }
            long bbb = 0;
            int[] d = new int[z.size() + 1];
            for (int w = z.size() - 1; w >= 0; w--) {
                d[w] = (d[w + 1] + z.get(w)) % mod;
            }
            int[] e = new int[d.length + 1];
            int[] f = new int[d.length + 1];
            for (int w = 0; w < d.length; w++) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = (f[w] - (w * d[w]) % mod + mod) % mod;
            }
            for (int jj = 0; jj < z.size(); jj++) {
                long ccc = 0;
                int L = jj + 2;
                int R = Math.min(z.size() - 1, i + jj);
                if (R >= L) {
                    ccc = (ccc + (e[R + 1] - e[L] + mod) % mod * (i + 1 + jj) % mod
                            + (f[R + 1] - f[L] + mod) % mod) % mod;
                }
                bbb = (bbb + ccc * z.get(jj)) % mod;
            }
            aaa = (aaa + bbb * A(n, n - i)) % mod;
            z = nz;
        }
        System.out.println(aaa % mod);
    }
}

