import sys
sys.stderr = sys.stdout

def factorial_product(n, mod):
    c = [0] * (n + 1)
    c[n] = 1
    for k in range(n - 1, -1, -1):
        c[k] = (c[k + 1] * (k + 1)) % mod
        if c[k] == 0:
            break
    return c

def build_tables(n, mod):
    tables = [[[1]]]
    for idx in range(n - 1):
        old = tables[idx]
        width = idx + 1
        nrows = len(old) + width
        new = [[0] * (width + 1) for _ in range(nrows)]
        for j, row in enumerate(old):
            for col, value in enumerate(row):
                for off in range(width):
                    new[j + off][col] = (new[j + off][col] + value) % mod
                new[j + width][width] = (new[j + width][width] + value) % mod
        tables.append(new)
    return tables

def contribution(rows, mod, coeff):
    R = len(rows)
    D = len(rows[0])
    pref = [[0] * D for _ in range(R)]
    for j in range(R):
        acc = 0
        for col in range(D - 1, -1, -1):
            acc = (acc + rows[j][col]) % mod
            pref[j][col] = acc
    for j in range(1, R):
        for col in range(D):
            pref[j][col] = (pref[j][col] + pref[j - 1][col]) % mod
    total = 0
    for j in range(1, R):
        for col in range(D - 1):
            total = (total + rows[j][col] * pref[j - 1][col + 1]) % mod
    return (total * coeff) % mod

def solve(n, mod):
    c = factorial_product(n, mod)
    tables = build_tables(n, mod)
    ans = 0
    for i in range(1, n):
        ans = (ans + contribution(tables[i], mod, c[i + 1])) % mod
    return ans

def main():
    n, m = map(int, input().split())
    print(solve(n, m))

if __name__ == "__main__":
    main()

