            w = 0;
            while (w < e.length - 1) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = (f[w] - w * d[w] % mod + mod) % mod;
                w++;
            }

            int R_ = lenLst;
            long temp = 0;
            int jjStart = Math.max(0, lenLst - i);
            int jj = jjStart;
            while (jj < lenLst - 2) {
                int L = jj + 2;
                temp = (temp + ((e[R_] - e[L] + mod) % mod * (i + 1 + jj) % mod + (f[R_] - f[L] + mod) % mod) * lst.get(jj) % mod) % mod;
                jj++;
            }

            jj = 0;
            while (jj < lenLst - i) {
                int L = jj + 2;
                int R2 = i + jj;
                if (R2 + 1 <= R_) {
                    temp = (temp + ((e[R2 + 1] - e[L] + mod) % mod * (i + 1 + jj) % mod + (f[R2 + 1] - f[L] + mod) % mod) * lst.get(jj) % mod) % mod;
                }
                jj++;
            }

            total = (total + temp * A(n, n - i, fact) % mod) % mod;
            lst.clear();
            for (long val : nz) lst.add(val);
            i++;
        }

        System.out.println(total % mod);
    }

    static long A(int n, int k, long[] fact) {
        return fact[n] / fact[n - k];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int mod = Integer.parseInt(parts[1]);

        if (n == 1) {
            System.out.println(0);
            return;
        }

        List<Integer> lst = new ArrayList<>();
        lst.add(1);
        long total = 0;

        for (int i = 2; i <= n; i++) {
            int lenLst = lst.size();
            int nLen = (i - 1) * i / 2 + 1;

            // compute d = reversed(accumulate(reversed(lst), mod sum)) + [0]
            List<Integer> reversedLst = new ArrayList<>(lst);
            Collections.reverse(reversedLst);
            List<Integer> accRev = accumulate(reversedLst, mod);
            Collections.reverse(accRev);
            List<Integer> d = new ArrayList<>(accRev);
            d.add(0); // d length = lenLst + 1

            // compute nz
            List<Integer> nz = new ArrayList<>();
            for (int w = 0; w < nLen; w++) {
                int left = Math.max(0, w + 1 - i);
                int right = Math.min(lenLst, w + 1);
                int val = (d.get(left) - d.get(right) + mod) % mod;
                nz.add(val);
            }

            // compute term_e = accumulate(d, mod sum)
            List<Integer> termE = accumulate(d, mod);
            // e = [0] + term_e
            List<Integer> e = new ArrayList<>();
            e.add(0);
            e.addAll(termE); // e length = lenLst + 2

            // compute term_f_w = [-w * d[w] % mod]
            List<Integer> termFw = new ArrayList<>();
            for (int w = 0; w < d.size(); w++) {
                long val = (-w * (long) d.get(w)) % mod;
                if (val < 0) val += mod;
                termFw.add((int) val);
            }
            // term_f = accumulate(term_f_w, mod sum)
            List<Integer> termF = accumulate(termFw, mod);
            // f = [0] + term_f
            List<Integer> f = new ArrayList<>();
            f.add(0);
            f.addAll(termF); // f length = lenLst + 2

            // compute temp
            long temp = 0;

            // sum1: jj from max(0, lenLst - i) to lenLst - 3 inclusive (since range end exclusive)
            int start1 = Math.max(0, lenLst - i);
            int end1 = lenLst - 2; // exclusive
            for (int jj = start1; jj < end1; jj++) {
                long part = ((long)(e.get(lenLst) - e.get(jj + 2) + mod) % mod) * (i + 1 + jj) % mod;
                part = (part + (long)(f.get(lenLst) - f.get(jj + 2) + mod) % mod) % mod;
                temp = (temp + part * lst.get(jj)) % mod;
            }

            // sum2: jj from 0 to lenLst - i - 1 inclusive
            int end2 = lenLst - i; // exclusive
            for (int jj = 0; jj < end2; jj++) {
                long part = ((long)(e.get(i + jj + 1) - e.get(jj + 2) + mod) % mod) * (i + 1 + jj) % mod;
                part = (part + (long)(f.get(i + jj + 1) - f.get(jj + 2) + mod) % mod) % mod;
                temp = (temp + part * lst.get(jj)) % mod;
            }

            // compute product = (i+1)*...*n mod mod
            long prod = 1;
            for (int k = i + 1; k <= n; k++) {
                prod = (prod * k) % mod;
            }
            total = (total + temp * prod) % mod;

            lst = nz;
        }

        System.out.println(total % mod);
    }

    // helper: accumulate with modulo addition
    private static List<Integer> accumulate(List<Integer> list, int mod) {
        List<Integer> result = new ArrayList<>();
        long sum = 0;
        for (int val : list) {
            sum = (sum + val) % mod;
            result.add((int) sum);
        }
        return result;
    }
}

