public class Main {
    public static void main(String[] args) {
        solve();
    }

    public static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();

        if (n == 1) {
            System.out.println(0);
            return;
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % mod;
        }

        long[] lst = new long[1];
        lst[0] = 1;
        long total = 0;
        int i = 2;
        while (i <= n) {
            int len_lst = lst.length;
            int n_len = (i - 1) * i / 2 + 1;
            long[] nz = new long[n_len];

            long[] d = new long[len_lst + 1];
            int pos = len_lst - 1;
            while (pos >= 0) {
                d[pos] = (d[pos + 1] + lst[pos]) % mod;
                pos--;
            }

            for (int w = 0; w < n_len; w++) {
                int L = Math.max(0, w + 1 - i);
                int R = Math.min(len_lst - 1, w);
                nz[w] = (d[L] - d[R + 1] + mod) % mod;
            }

            long[] e = new long[len_lst + 2];
            long[] f = new long[len_lst + 2];
            for (int w = 0; w <= len_lst; w++) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = (f[w] - (long) w * d[w] % mod + mod) % mod;
            }

            long temp = 0;
            int R = len_lst;
            int jj = Math.max(0, len_lst - i);
            while (jj < len_lst - 2) {
                int L = jj + 2;
                long term1 = (e[R] - e[L] + mod) % mod;
                long term2 = (f[R] - f[L] + mod) % mod;
                temp = (temp + (term1 * (i + 1 + jj) + term2) % mod * lst[jj]) % mod;
                jj++;
            }

            jj = 0;
            while (jj < len_lst - i) {
                int L = jj + 2;
                int R2 = i + jj;
                long term1 = (e[R2 + 1] - e[L] + mod) % mod;
                long term2 = (f[R2 + 1] - f[L] + mod) % mod;
                temp = (temp + (term1 * (i + 1 + jj) + term2) % mod * lst[jj]) % mod;
                jj++;
            }

            total = (total + temp * A(n, n - i, fact, mod)) % mod;
            lst = nz;
            i++;
        }

        System.out.println(total % mod);
    }

    public static long A(int n, int k, long[] fact, int mod) {
        if (k < 0 || k > n) return 0;
        return fact[n] * modInverse(fact[n - k], mod) % mod;
    }

    public static long modInverse(long a, int mod) {
        return powMod(a, mod - 2, mod);
    }

    public static long powMod(long a, long e, int mod) {
        long res = 1;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return res;
    }
}

