public class Main {
    static long addMod(long a, long b, long mod) {
        a %= mod;
        b %= mod;
        if (a >= mod - b) {
            return a - (mod - b);
        } else {
            return a + b;
        }
    }

    static long subMod(long a, long b, long mod) {
        a %= mod;
        b %= mod;
        if (a >= b) {
            return a - b;
        } else {
            return a - b + mod;
        }
    }

    static long mulMod(long a, long b, long mod) {
        a %= mod;
        b %= mod;
        long res = 0;
        while (b > 0) {
            if ((b & 1) == 1) {
                if (res >= mod - a) {
                    res = res - (mod - a);
                } else {
                    res = res + a;
                }
            }
            if (a >= mod - a) {
                a = a - (mod - a);
            } else {
                a = a + a;
            }
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append(' ');
        }
        String[] tokens = sb.toString().trim().split("\\s+");
        if (tokens.length < 2) return;

        int n = Integer.parseInt(tokens[0]);
        long mod = Long.parseLong(tokens[1]);

        if (n == 1) {
            System.out.println(0);
            return;
        }

        long[] suffixProd = new long[n + 2];
        suffixProd[n + 1] = 1 % mod;
        for (int i = n; i >= 1; i--) {
            suffixProd[i] = mulMod(suffixProd[i + 1], i, mod);
        }

        long[] lst = new long[]{1 % mod};
        long total = 0;

        for (int i = 2; i <= n; i++) {
            int len_lst = lst.length;
            long nLenLong = (long) (i - 1) * i / 2 + 1;
            int n_len = (int) nLenLong;
            long[] nz = new long[n_len];

            long[] d = new long[len_lst + 1];
            for (int w = len_lst - 1; w >= 0; w--) {
                d[w] = addMod(d[w + 1], lst[w], mod);
            }

            for (int w = 0; w < n_len; w++) {
                int L = Math.max(0, w + 1 - i);
                int R = Math.min(len_lst - 1, w);
                nz[w] = subMod(d[L], d[R + 1], mod);
            }

            int dlen = len_lst + 1;
            long[] e = new long[dlen + 1];
            long[] f = new long[dlen + 1];
            for (int w = 0; w < dlen; w++) {
                e[w + 1] = addMod(e[w], d[w], mod);
                long prod = mulMod(w % mod, d[w], mod);
                f[w + 1] = subMod(f[w], prod, mod);
            }

            long temp = 0;

            int start1 = Math.max(0, len_lst - i);
            int stop1 = len_lst - 2;
            for (int jj = start1; jj < stop1; jj++) {
                int L = jj + 2;
                long diffE = subMod(e[len_lst], e[L], mod);
                long diffF = subMod(f[len_lst], f[L], mod);
                long coef = ((long) i + 1 + jj) % mod;
                long inner = addMod(mulMod(diffE, coef, mod), diffF, mod);
                temp = addMod(temp, mulMod(inner, lst[jj], mod), mod);
            }

            int limit2 = len_lst - i;
            for (int jj = 0; jj < limit2; jj++) {
                int L = jj + 2;
                int R2 = i + jj;
                long diffE = subMod(e[R2 + 1], e[L], mod);
                long diffF = subMod(f[R2 + 1], f[L], mod);
                long coef = ((long) i + 1 + jj) % mod;
                long inner = addMod(mulMod(diffE, coef, mod), diffF, mod);
                temp = addMod(temp, mulMod(inner, lst[jj], mod), mod);
            }

            total = addMod(total, mulMod(temp, suffixProd[i + 1], mod), mod);
            lst = nz;
        }

        System.out.println(total % mod);
    }
}

