            prodRatio[i] = (prodRatio[i + 1] * (i + 1)) % mod;
        }

        int[] lst = new int[]{1};
        long ans = 0;
        int i = 2;

        while (i <= n) {
            int lenLst = lst.length;
            int nLen = (i - 1) * i / 2 + 1;
