            long[] d = new long[lenLst + 1];
            for (int idx = lenLst - 1; idx >= 0; idx--) {
                d[idx] = (d[idx + 1] + lst[idx]) % mod;
            }

            for (int nzIdx = 0; nzIdx < nLen; nzIdx++) {
                int L = Math.max(0, nzIdx + 1 - i);
                int R = Math.min(lenLst - 1, nzIdx);
                long val = (d[L] - d[R + 1]) % mod;
                if (val < 0) val += mod;
                nz[nzIdx] = (int) val;
            }

            long[] e = new long[lenLst + 2];
            long[] f = new long[lenLst + 2];
            for (int pos = 0; pos < lenLst + 1; pos++) {
                e[pos + 1] = (e[pos] + d[pos]) % mod;
                f[pos + 1] = (f[pos] - (long) pos * d[pos]) % mod;
                if (f[pos + 1] < 0) f[pos + 1] += mod;
            }

            long temp = 0;
            int start = Math.max(0, lenLst - i);
            for (int j = start; j < lenLst - 2; j++) {
                int L = j + 2;
                long term1 = (e[lenLst] - e[L]) % mod;
                if (term1 < 0) term1 += mod;
                long term2 = (f[lenLst] - f[L]) % mod;
                if (term2 < 0) term2 += mod;
                long add = (term1 * (i + 1 + j) + term2) % mod;
                add = (add * lst[j]) % mod;
                temp = (temp + add) % mod;
            }

            for (int j = 0; j < lenLst - i; j++) {
                int L = j + 2;
                int R2 = i + j;
                long term1 = (e[R2 + 1] - e[L]) % mod;
                if (term1 < 0) term1 += mod;
                long term2 = (f[R2 + 1] - f[L]) % mod;
                if (term2 < 0) term2 += mod;
                long add = (term1 * (i + 1 + j) + term2) % mod;
                add = (add * lst[j]) % mod;
                temp = (temp + add) % mod;
            }

            ans = (ans + temp * prodRatio[i]) % mod;
            lst = nz;
            i++;
        }

        System.out.println(ans % mod);
