public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());
        System.out.println(solve(n, mod));
    }

    static int solve(int n, int mod) {
        int m = n * (n - 1) / 2;
        int size = n * (n - 1) + 1;
        int[] dp_prev = new int[size];
        int[] dp1_prev = new int[size];
        dp_prev[m] = 1;
        for (int i = 2; i <= n; i++) {
            int start = m - (i - 1) * (i - 2) / 2;
            int end = m + (i - 1) * (i - 2) / 2;
            int[] dp_cur = new int[size];
            int[] dp1_cur = new int[size];
            for (int x = start; x <= end; x++) {
                dp1_cur[x] = (int)((long)dp1_prev[x] * i % mod);
            }
            for (int x = start; x <= end; x++) {
                int v = dp_prev[x];
                if (v != 0) {
                    for (int d = -i + 1; d < i; d++) {
                        int idx = x + d;
                        if (idx >= 0 && idx < size) {
                            dp_cur[idx] = (int)((dp_cur[idx] + (long)v * (i - Math.abs(d))) % mod);
                        }
                    }
                    for (int d = 1; d < i; d++) {
                        int idx = x - d;
                        if (idx >= 0 && idx < size) {
                            dp1_cur[idx] = (int)((dp1_cur[idx] + (long)v * (i - d)) % mod);
                        }
                    }
                }
            }
            dp_prev = dp_cur;
            dp1_prev = dp1_cur;
        }
        long ans = 0;
        for (int i = m + 1; i < size; i++) {
            ans = (ans + dp1_prev[i]) % mod;
        }
        return (int)ans;
    }
}

