            int low = s - (i - 1);
            int high = e + (i - 1);
            for (int x = low; x <= high; x++) {
                dpCur[x] = 0;
            }
            for (int x = low; x <= e; x++) {
                dp1Cur[x] = 0;
            }

            // First loop: dp1Cur[x] = dp1Prev[x] * i % mod
