    public static long solve(int n, long mod) {
        if (n <= 3) {
            return 0;
        }
        long lastAns = 17;
        long ans = 17;
        int size = (n - 1) * (n - 2) / 2 + 1;
        long[][] record = new long[2][size + 1];
        record[0][0] = 1;
        record[0][1] = 2;
        record[0][2] = 2;
        record[0][3] = 1;
        int m = 4;
        int inv = 1;
        while (m < n) {
            int tpSize = m * (m - 1) / 2;
            ans = (m + 1) * lastAns % mod;
            long tp = 0;
            for (int i = 0; i < m; i++) {
                tp += record[inv ^ 1][i];
                record[inv][i] = tp % mod;
            }
            for (int i = m; i <= tpSize / 2; i++) {
                tp += record[inv ^ 1][i];
                tp -= record[inv ^ 1][i - m];
                record[inv][i] = tp % mod;
            }
            for (int i = 0; i <= tpSize / 2; i++) {
                record[inv][tpSize - i] = record[inv][i];
            }
            long total = 0;
            for (int i = 0; i < tpSize - 1; i++) {
                long innerTp = 0;
                int startJ = Math.max(1, -tpSize + i + m + 2);
                for (int j = startJ; j <= m; j++) {
                    innerTp += j * record[inv][m + 2 - j + i];
                }
                total += record[inv][i];
                total %= mod;
                innerTp %= mod;
                innerTp *= total;
                innerTp %= mod;
