    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        long result = solve(n, mod);
        System.out.println(result);
        sc.close();
    }

    static long solve(int n, int mod) {
        if (n <= 3) {
            return 0;
        }
        long last_ans = 17;
        long ans = 17;
        int size = (n - 1) * (n - 2) / 2 + 1;
        int inv = 1;
        long[] r0 = new long[size + 1];
        long[] r1 = new long[size + 1];
        r0[0] = 1;
        r0[1] = 2;
        r0[2] = 2;
        r0[3] = 1;

        for (int m = 4; m < n; m++) {
            int tp_size = m * (m - 1) / 2;
            ans = ((long)(m + 1) * last_ans) % mod;
            long tp = 0;
            long[] cur = (inv == 0) ? r0 : r1;
            long[] prev = (inv == 1) ? r0 : r1;

            // first loop
            for (int i = 0; i < m; i++) {
                tp += prev[i];
                cur[i] = tp % mod;
            }

            // second loop
            int half = tp_size / 2;
            for (int i = m; i <= half; i++) {
                tp += prev[i] - prev[i - m];
                cur[i] = tp % mod;
            }

            // third loop: mirror
            for (int i = 0; i <= half; i++) {
                cur[tp_size - i] = cur[i];
            }

            // nested loops
            long total = 0;
            for (int i = 0; i < tp_size - 1; i++) {
                long inner = 0;
                int lo = Math.max(1, -tp_size + i + m + 2);
                for (int j = lo; j <= m; j++) {
                    inner += (long)j * cur[m + 2 - j + i];
                }
                total = (total + cur[i]) % mod;
                inner = (inner % mod) * total % mod;
                ans = (ans + inner) % mod;
            }

            last_ans = ans;
            inv ^= 1;
        }
        return ans % mod;
    }
}

