import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();
        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        int h = Integer.parseInt(parts[1]);
        BigInteger result = compute(n, n).subtract(compute(n, h > 0 ? h - 1 : 0));
        System.out.println(result);
    }

    public static BigInteger compute(int n, int h) {
        Map<String, BigInteger> memo = new HashMap<>();
        return recurse(n, h, memo);
    }

    private static BigInteger recurse(int n, int h, Map<String, BigInteger> memo) {
        String key = n + "," + h;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        BigInteger result;
        if (n == 0) {
            result = BigInteger.ONE;
        } else if (h == 0) {
            result = BigInteger.ZERO;
        } else {
            BigInteger total = BigInteger.ZERO;
            for (int i = 0; i < n; i++) {
                BigInteger left = recurse(i, h - 1, memo);
                BigInteger right = recurse(n - 1 - i, h - 1, memo);
                total = total.add(left.multiply(right));
            }
            result = total;
        }
        memo.put(key, result);
        return result;
    }
}

