        long key = ((long)n << 32) | (h & 0xffffffffL);
        BigInteger cached = cache.get(key);
        if (cached != null) return cached;
        BigInteger res;
        if (n == 0) {
            res = BigInteger.ONE;
        } else if (h == 0) {
            res = BigInteger.ZERO;
        } else {
            res = BigInteger.ZERO;
            for (int i = 0; i < n; i++) {
                res = res.add(go(i, h - 1).multiply(go(n - 1 - i, h - 1)));
            }
        }
        cache.put(key, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        System.out.println(go(n, n).subtract(go(n, Math.max(0, h - 1))));
    }
}

