public class Main {
    static BigInteger[][] dp;
    static int n;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int h = sc.nextInt();
        dp = new BigInteger[n + 1][n + 1];
        // Initialize base cases
        dp[0][0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            dp[0][i] = BigInteger.ZERO;
            dp[i][0] = BigInteger.ZERO;
        }
        // Fill DP table
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                calc(i, j);
            }
        }
        // Compute result sum
        BigInteger result = BigInteger.ZERO;
        for (int i = h; i <= n; i++) {
            result = result.add(dp[n][i]);
        }
        System.out.println(result);
        sc.close();
    }

    static BigInteger calc(int a, int b) {
        if (dp[a][b] != null) {
            return dp[a][b];
        }
        BigInteger total = BigInteger.ZERO;
        for (int m = 1; m <= a; m++) {
            // First term: calc(m-1, b-1) * sum_{i=0}^{b-1} calc(a-m, i)
            BigInteger term1 = calc(m - 1, b - 1);
            BigInteger sum1 = BigInteger.ZERO;
            for (int i = 0; i < b; i++) {
                sum1 = sum1.add(calc(a - m, i));
            }
            total = total.add(term1.multiply(sum1));

            // Second term: calc(a-m, b-1) * sum_{i=0}^{b-2} calc(m-1, i)
            BigInteger term2 = calc(a - m, b - 1);
            BigInteger sum2 = BigInteger.ZERO;
            for (int i = 0; i < b - 1; i++) {
                sum2 = sum2.add(calc(m - 1, i));
            }
            total = total.add(term2.multiply(sum2));
        }
        dp[a][b] = total;
        return total;
    }
}

import java.math.BigInteger;
