public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        sc.close();

        BigInteger[][] dp = new BigInteger[n + 1][n + 1];
        BigInteger[][] pref = new BigInteger[n + 1][n + 2]; // pref[row][k] = sum_{i=0}^{k} dp[row][i]

        // Initialize all to zero
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = BigInteger.ZERO;
            }
            for (int j = 0; j <= n + 1; j++) {
                pref[i][j] = BigInteger.ZERO;
            }
        }

        dp[0][0] = BigInteger.ONE;
        // Compute prefix for row 0
        pref[0][0] = dp[0][0];
        for (int k = 1; k <= n; k++) {
            pref[0][k] = pref[0][k - 1].add(dp[0][k]); // dp[0][k] is zero for k>0
        }

        for (int nodes = 1; nodes <= n; nodes++) {
            for (int height = 1; height <= n; height++) {
                BigInteger total = BigInteger.ZERO;
                for (int left_nodes = 1; left_nodes <= nodes; left_nodes++) {
                    int right_nodes = nodes - left_nodes;
                    // sum1 = sum_{i=0}^{height-1} dp[right_nodes][i]
                    BigInteger sum1 = pref[right_nodes][height - 1];
                    BigInteger term1 = dp[left_nodes - 1][height - 1].multiply(sum1);
                    // sum2 = sum_{i=0}^{height-2} dp[left_nodes-1][i]
                    BigInteger sum2 = (height - 2 >= 0) ? pref[left_nodes - 1][height - 2] : BigInteger.ZERO;
                    BigInteger term2 = dp[right_nodes][height - 1].multiply(sum2);
                    total = total.add(term1).add(term2);
                }
                dp[nodes][height] = total;
            }
            // Compute prefix for current row
            pref[nodes][0] = dp[nodes][0];
            for (int k = 1; k <= n; k++) {
                pref[nodes][k] = pref[nodes][k - 1].add(dp[nodes][k]);
            }
        }

        BigInteger result = BigInteger.ZERO;
        for (int i = h; i <= n; i++) {
            result = result.add(dp[n][i]);
        }
        System.out.println(result);
    }
}

