    static Map<Integer, Map<Integer, Map<Integer, Long>>> cacheLimit = new HashMap<>();

    static long searchall(int lo, int hi) {
        if (lo == hi) {
            return 1;
        }
        Map<Integer, Long> inner = cacheAll.get(lo);
        if (inner != null) {
            Long cached = inner.get(hi);
            if (cached != null) {
                return cached;
            }
        }
        long total = 0;
        total += searchall(lo + 1, hi);
        total += searchall(lo, hi - 1);
        for (int i = lo + 1; i < hi; i++) {
            total += searchall(lo, i - 1) * searchall(i + 1, hi);
        }
        if (inner == null) {
            inner = new HashMap<>();
            cacheAll.put(lo, inner);
        }
        inner.put(hi, total);
        return total;
    }

    static long searchlimit(int lo, int hi, int depth) {
        if (lo == hi) {
            if (depth < m) {
                return 1;
            }
            return 0;
        }
        Map<Integer, Map<Integer, Long>> inner1 = cacheLimit.get(lo);
        if (inner1 != null) {
            Map<Integer, Long> inner2 = inner1.get(hi);
            if (inner2 != null) {
                Long cached = inner2.get(depth);
                if (cached != null) {
                    return cached;
                }
            }
        }
        long total = 0;
        total += searchlimit(lo + 1, hi, depth + 1);
        total += searchlimit(lo, hi - 1, depth + 1);
