import java.math.BigInteger;
import java.util.HashMap;
import java.util.Objects;
import java.util.Scanner;

public class Main {
    static class Pair {
        int n, h;
        Pair(int n, int h) {
            this.n = n;
            this.h = h;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return n == pair.n && h == pair.h;
        }
        @Override
        public int hashCode() {
            return Objects.hash(n, h);
        }
    }

    static BigInteger get_dp(int nn, int hh, HashMap<Pair, BigInteger> dp, BigInteger[] cat) {
        if (nn < 0 || hh <= 0) return BigInteger.ZERO;
        // check nn >= 2^(hh-1)
        if (BigInteger.valueOf(nn).compareTo(BigInteger.ONE.shiftLeft(hh - 1)) >= 0) {
            return BigInteger.ZERO;
        }
        if (nn < 2) return BigInteger.ONE;
        if (nn < hh) return cat[nn];
        return dp.get(new Pair(nn, hh));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        sc.close();

        // Catalan numbers
        BigInteger[] cat = new BigInteger[n + 1];
        cat[0] = BigInteger.ONE;
        if (n >= 1) cat[1] = BigInteger.ONE;
        for (int m = 2; m <= n; m++) {
            BigInteger total = BigInteger.ZERO;
            for (int i = 0; i < m; i++) {
                total = total.add(cat[i].multiply(cat[m - 1 - i]));
            }
            cat[m] = total;
        }

        HashMap<Pair, BigInteger> dp = new HashMap<>();
        for (int hh = 1; hh <= h; hh++) {
            for (int nn = 0; nn <= n; nn++) {
                if (nn < 0 || hh <= 0) continue;
                if (BigInteger.valueOf(nn).compareTo(BigInteger.ONE.shiftLeft(hh - 1)) >= 0) continue;
                if (nn < 2) {
                    dp.put(new Pair(nn, hh), BigInteger.ONE);
                } else if (nn < hh) {
                    dp.put(new Pair(nn, hh), cat[nn]);
                } else {
                    BigInteger total = BigInteger.ZERO;
                    for (int i = 0; i < nn; i++) {
                        BigInteger left = get_dp(i, hh - 1, dp, cat);
                        BigInteger right = get_dp(nn - 1 - i, hh - 1, dp, cat);
                        total = total.add(left.multiply(right));
                    }
                    dp.put(new Pair(nn, hh), total);
                }
            }
        }

        BigInteger result = cat[n].subtract(get_dp(n, h, dp, cat));
        System.out.println(result);
    }
}

