public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int h = Integer.parseInt(parts[1]);

        // Initialize s with all ones (Catalan numbers will be computed)
        BigInteger[] s = new BigInteger[n + 1];
        for (int i = 0; i <= n; i++) {
            s[i] = BigInteger.ONE;
        }

        // Compute Catalan numbers: s[m] = sum_{k=0}^{m-1} s[k] * s[m-1-k]
        for (int m = 1; m <= n; m++) {
            BigInteger sum = BigInteger.ZERO;
            for (int k = 0; k < m; k++) {
                sum = sum.add(s[k].multiply(s[m - 1 - k]));
            }
            s[m] = sum;
        }

        // t = s (copy)
        BigInteger[] t = s.clone();

        // Perform h iterations
        for (int iter = 0; iter < h; iter++) {
            BigInteger[] conv_st = new BigInteger[n + 1];
            BigInteger[] conv_tt = new BigInteger[n + 1];

            // Compute conv_st and conv_tt for m = 0..n
            for (int m = 0; m <= n; m++) {
                BigInteger sum_st = BigInteger.ZERO;
                BigInteger sum_tt = BigInteger.ZERO;
                for (int k = 0; k < m; k++) {
                    sum_st = sum_st.add(s[k].multiply(t[m - 1 - k]));
                    sum_tt = sum_tt.add(t[k].multiply(t[m - 1 - k]));
                }
                conv_st[m] = sum_st;
                conv_tt[m] = sum_tt;
            }

            // Build new t: t[0] = 0, t[m] = 2*conv_st[m] - conv_tt[m] for m>=1
            BigInteger[] new_t = new BigInteger[n + 1];
            new_t[0] = BigInteger.ZERO;
            for (int m = 1; m <= n; m++) {
                new_t[m] = conv_st[m].multiply(BigInteger.valueOf(2)).subtract(conv_tt[m]);
            }
            t = new_t;
        }

        // Output t[n]
        System.out.println(t[n]);
    }
}

